const t=(title,note,minutes=60)=>({title,note,minutes});
export const research=[
{title:'Описать систему GaAs и режим накачки',why:'Для вашей текущей работы: поляритонный конденсат, ловушка и порог генерации. Тип ловушки и параметры образца пока не заданы.',result:'Одна схема системы и таблица параметров с единицами и источниками.',tasks:[t('Составить паспорт образца и эксперимента','Уточните у руководителя: геометрия и происхождение ловушки (структурная, оптическая или другая), размерность модели, температура, расстройка фотон–экситон, расщепление Раби, времена жизни, профиль и режим накачки. Не подставляйте «типичные для GaAs» числа без источника.'),t('Разобрать дисперсию экситона, фотона и поляритонов','Изобразите E(k) для несвязанных мод и ветвей LP/UP в модели двух связанных осцилляторов. Подпишите расстройку и определение расщепления Раби. Проверьте пределы большой положительной и отрицательной расстройки.'),t('Согласовать набор данных и ожидаемых графиков','Какие данные доступны: I(P), спектры, E(k), I(x,y), корреляции? Выберите конкретный рисунок статьи или набор лабораторных данных для воспроизведения. Зафиксируйте, что требуется: аналитический вывод, расчёт или обработка измерений.')],gate:'Не определён тип накачки — нельзя автоматически применять модель с некогерентным резервуаром. Уточните режим до следующего этапа.'},
{title:'Разобрать открытую GPE и резервуар',why:'Для нерезонансной некогерентной накачки: модель с усилением, потерями и резервуаром. Она не универсальна для всех режимов эксперимента.',result:'Вывод стационарного однородного порога и таблица смысла каждого члена.',tasks:[t('Выписать уравнения и проверить размерности','Учебная модель: iℏ∂tψ=[−ℏ²∇²/(2m)+V+gC|ψ|²+gR nR+iℏ(R nR−γC)/2]ψ; ∂t nR=P−(γR+R|ψ|²)nR. Здесь |ψ|² и nR — плотности в выбранной размерности, γ — скорости потерь, R — коэффициент рассеяния. P — скорость создания резервуара, не мощность лазера в мВт. Определите единицы всех параметров и нормировку ψ.'),t('Вывести однородный стационарный порог','При постоянной однородной накачке, линейном R nR и отсутствии пространственных потоков: nR,th=γC/R, Pth=γRγC/R. Выше порога |ψ|²=(P−Pth)/γC, nR=γC/R. Выведите из баланса усиления и потерь. Эти формулы не являются готовым порогом конечной ловушки.'),t('Проверить динамику на простом пределе','Сравните численную динамику плотностей ниже и выше Pth с аналитическим пределом. Используйте малое ненулевое начальное ψ; строго нулевое поле в детерминированной модели само не вырастет. Проверьте шаг времени и время выхода на режим.',90)],gate:'Не совпал аналитический предел — исправьте единицы, нормировку и баланс потерь до расчёта ловушки.'},
{title:'Рассчитать моды и плотность в ловушке',why:'Форма ловушки, накачки и резервуара влияет на выбранную моду и порог. Параметры берите из своей системы.',result:'V(r), профиль накачки, линейные моды и распределение плотности; проверка сходимости.',tasks:[t('Задать потенциал ловушки и линейные моды','Начните с согласованной одномерной геометрии, если это допустимое приближение. Постройте V(x), несколько энергий и |φn(x)|². Для оптической ловушки разделите структурный V и вклад резервуара gR nR.'),t('Добавить накачку и потери в пространственную модель','Сравните плотность |ψ(x,t)|² и nR(x,t) для нескольких уровней накачки. Фиксируйте начальные условия и границы области. Не предполагайте автоматически заселение основной моды.',90),t('Проверить сходимость и пространственные графики','Повторите расчёт с меньшим шагом времени и пространства, увеличьте область. Сравните интегральную плотность, энергию и форму моды. Постройте |ψ(x)|² и |ψ(k)|² с указанной нормировкой преобразования Фурье.',90)],gate:'Наблюдаемые особенности должны сохраняться при уточнении сетки. Порог неоднородной системы определяйте по её динамике или устойчивости, а не подстановкой в однородную формулу.'},
{title:'Собрать графики порогового поведения',why:'Нужно сопоставить несколько наблюдаемых величин и отдельно обозначить, что измерено, а что вычислено.',result:'Панель графиков с подписями осей, единицами, областью интегрирования и неопределённостями.',tasks:[t('Построить I(P), энергию и ширину линии','Для экспериментальных спектров: одинаковое правило вычитания фона, диапазон интегрирования и модель аппроксимации. Постройте интенсивность, энергию пика и FWHM от накачки; укажите спектральное разрешение. Излом или сужение сами по себе не определяют природу генерации.',90),t('Сопоставить спектры и распределения ниже и выше порога','Покажите E(k), пространственную интенсивность и распределение по импульсу при нескольких P. Сопоставьте с LP и несвязанной фотонной модой, учитывая сдвиг энергии. Запишите, какие измерения нужны для оценки сильной связи.',90),t('Проверить доступные данные о когерентности','Если есть измерения g¹ или g²(0), укажите метод, временное разрешение и ограничения. Детерминированная GPE без модели шума и измерения не предсказывает автоматически экспериментальные флуктуации или ширину линии. Если данных нет — так и укажите.')],gate:'Не называйте любую нелинейность «конденсацией». Составьте таблицу: наблюдение / возможное объяснение / недостающее измерение.'},
{title:'Разделить конденсацию и фотонный лазер',why:'Поляритонная генерация и обычный фотонный лазер требуют разных физических объяснений. Второй порог также не является универсальным доказательством потери сильной связи.',result:'Короткий доклад: модель, 4–6 графиков, выводы и вопросы руководителю.',tasks:[t('Составить таблицу признаков двух режимов','Сравните дисперсию и характер моды, сохранение сильной связи, пороговые зависимости, сдвиг энергии и когерентность. Отдельно выпишите, что ваша LP-GPE описывает и чего не описывает: переход к фотонному лазеру при разрушении сильной связи требует иной или расширенной модели.'),t('Собрать доклад по собственным графикам','Для каждого рисунка: вопрос, условия, оси, результат, альтернативное объяснение. Разделите «измерено», «получено в модели» и «предполагается». Не переносите параметры и выводы чужой ловушки на свой образец.',90),t('Обсудить с руководителем следующий расчёт','Покажите один наиболее спорный вывод и недостающие данные. Зафиксируйте согласованное действие и критерий проверки в ежедневнике.')],gate:'Итог формулируйте в пределах имеющихся данных. Если режим не различим, результатом является список измерений или расчётов, необходимых для различения.'}
];
